INSERT INTO ai_knowledge (title, content, tags, status, created_at, updated_at)
SELECT '项目常见问题与排障指南', '本指南基于当前 Weather Data Hub 代码和运行配置。平台包含工作台、用户、角色、菜单、GIS 标注、摄像头、官方灾害预警、知识库和 Agent 工作台。权限遵循 RBAC；页面或接口不可访问时检查对应 read 或 write 权限和菜单分配。摄像头监控已具备设备、快照、监控记录和告警模型，入口是 api cameras。设备接入流程是配置摄像头及可访问的流或快照来源，由快照分析生成监控记录和活动告警；代码存在不代表每台设备已经配置或连通。GIS 使用 PostGIS 的 gis feature，支持手工圈地、影像图层、Roboflow 和 SAM2.1 辅助圈地；写入失败时检查 gis write 权限、GeoJSON 面、坐标系和 Python Agent 服务。天气查询依赖外部天气服务，不等于本地历史气象仓库。知识库只有 ENABLED 文章进入 RAG；缺少项目事实时应补充知识文章，不应猜测。Agent 是只读查询和回答能力，停止接收只中断浏览器接收。Jev 负责 weather、dashboard、gis、current user、system knowledge 和 chat 的意图路由；执行记录出现 Jev intent route 才表示本次实际命中。Jev 使用 TypeSafe API、Bearer Key、jev latest 模型和 Choice criteria；低置信度或失败会回退规划器。部署异常先检查 docker compose ps、api health、容器日志和环境变量。后端启动失败优先检查 YAML 缩进与配置绑定；构建下载失败通常是 Maven 网络或 TLS 问题，可重试并使用缓存。不要在没有代码、配置或实时数据证据时声称系统已具备任意 SQL、自动运维、Agent 自动修改业务数据、完整历史气象仓库或所有设备已经接入。', 'FAQ,排障,权限,GIS,摄像头,设备监控,知识库,Agent,Jev,部署,能力边界', 'ENABLED', NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM ai_knowledge WHERE title = '项目常见问题与排障指南');
